transforms.before:
#page-title {
 color: rgb(var(--swatch-menutxt-dark-color));
 -webkit-animation: neon-end 300ms ease-in-out 1 normal forwards;
 animation: neon-end 300ms ease-in-out 1 normal forwards;
 cursor: default;
 transition: all 0.5s;
 border-bottom: none;
}

transforms.after:
#page-title {
 /* The JP runtime's article title sits on the near-black body panel.
    The legacy selector used the dark menu-text token here, making the
    title disappear against the imported crimson backdrop. */
 color: rgb(var(--swatch-text-light));
 -webkit-animation: neon-end 300ms ease-in-out 1 normal forwards;
 animation: neon-end 300ms ease-in-out 1 normal forwards;
 cursor: default;
 transition: all 0.5s;
 border-bottom: none;
}

#page-title a { color: inherit; }
